2	use std::fmt::{self, Display, Formatter};
3	use std::path::Path;
4	
5	use typst::text::{
6	    AxisValue, FontAxis, FontInfo, FontStretch, FontVariant, FontWeight, StandardAxes,
7	};
8	use typst_kit::fonts::{self, FontPath, FontStore};
9	
10	use crate::args::{FontArgs, FontsCommand};
11	
12	/// Execute a font listing command.
13	pub fn fonts(command: &FontsCommand) {
14	    let fonts = discover_fonts(&command.font);
15	
16	    for (family, indices) in fonts.book().families() {
17	        println!("{family}");
18	        if command.variants {
19	            let mut indices = indices.peekable();
20	            while let Some(index) = indices.next() {
21	                let info = fonts.book().info(index).unwrap();
22	                let path = fonts
23	                    .source(index)
24	                    .and_then(|source| (source as &dyn Any).downcast_ref::<FontPath>())
25	                    .map(|font| font.path.as_path());
26	                let last = indices.peek().is_none();
27	                let variant =
28	                    typst_utils::display(|f| write_variant(f, info, path, last));
29	                print!("{variant}");
30	            }
31	            println!();
32	        }
33	    }
34	}
35	
36	/// Discovers the fonts as specified by the CLI flags.
37	#[typst_macros::time(name = "discover fonts")]
38	pub fn discover_fonts(args: &FontArgs) -> FontStore {
39	    let mut fonts = FontStore::new();
40	
41	    if !args.ignore_system_fonts {
42	        fonts.extend(fonts::system());
43	    }
